import assert from 'node:assert/strict';
import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { pathToFileURL } from 'node:url';
import { transport, generated, config, preparation, payload, commands, run, digest, writeJson, guardCarrier, absentSource } from './status-agent-common.mjs';

// Generated-project process. Only four independently authored files are supplied.
guardCarrier();
absentSource();
const authored = JSON.parse(readFileSync(path.join(transport, '.github/payload/status-authored-files.json'), 'utf8'));
const authoredPaths = ['packages/status/src/index.ts', 'packages/status/README.md', 'packages/status/test/status.test.ts', 'packages/status/test/status.runtime.test.ts'];
assert.equal(authored.provenance.ownTransportSha, config.authoredTransportSha);
assert.deepEqual(authored.files.map((file) => file.path).sort(), [...authoredPaths].sort());
for (const file of authored.files) assert.equal(digest(Buffer.from(file.content)), file.sha256);
const { contentId } = await import(pathToFileURL(path.join(generated, 'tools/quality/gate.ts')).href);
const { walk } = await import(pathToFileURL(path.join(generated, 'tools/generators/files.ts')).href);
const { workspacePackages } = await import(pathToFileURL(path.join(generated, 'tools/quality/graph.ts')).href);
function inventory() {
  const excluded = new Set(workspacePackages(generated).flatMap((pkg) => [
    pkg.directory + '/dist', pkg.directory + '/artifacts', pkg.directory + '/test-results', pkg.directory + '/playwright-report',
    ...(pkg.runtime === 'worker' ? [pkg.directory + '/.cloudflare', pkg.directory + '/.wrangler', pkg.directory + '/src/routeTree.gen.ts'] : []),
    ...(pkg.runtime === 'desktop' ? [pkg.directory + '/src-tauri/target', pkg.directory + '/src-tauri/icons', pkg.directory + '/src-tauri/gen', pkg.directory + '/src-tauri/permissions/autogenerated'] : []),
  ]));
  const result = new Map();
  for (const directory of ['tools', 'docs', '.agents', '.github', 'packages']) {
    if (!existsSync(path.join(generated, directory))) continue;
    for (const file of walk(path.join(generated, directory), directory, new Set(['node_modules']), excluded)) result.set(file, readFileSync(path.join(generated, file)));
  }
  for (const file of ['package.json', 'pnpm-lock.yaml', 'pnpm-workspace.yaml', 'mise.toml', 'mise.security.toml', 'mise.o11y.toml', 'tsconfig.json', 'vite.config.ts', '.template.json', 'AGENTS.md', 'README.md', 'CLAUDE.md', 'knip.ts', '.gitignore', '.gitattributes', '.semgrepignore', 'renovate.json', 'LICENSE']) {
    if (existsSync(path.join(generated, file))) result.set(file, readFileSync(path.join(generated, file)));
  }
  return result;
}
const expectedOrigin = JSON.parse(readFileSync(path.join(preparation, 'generated-origin.json'), 'utf8')).origin;
assert.equal(expectedOrigin.sha, config.source.sha);
assert.equal(expectedOrigin.dirty, false);
const baselineState = JSON.parse(readFileSync(path.join(generated, '.template.json'), 'utf8'));
assert.deepEqual(baselineState.origin, expectedOrigin);
assert.ok(!existsSync(path.join(generated, '.git')));
assert.ok(!existsSync(path.join(generated, 'node_modules')));
assert.ok(!existsSync(path.join(generated, 'packages/status')));
const baselineFiles = inventory();
assert.ok(baselineFiles.size > 0);
writeJson('pristine-baseline-template.json', baselineState);
writeJson('pristine-baseline-files.json', [...baselineFiles].map(([file, bytes]) => ({ path: file, sha256: digest(bytes), size: bytes.length })));
const baselineContentId = contentId(generated);
run(['git', 'init', '--template=', '--initial-branch=main'], generated, 'baseline-init');
run(['git', 'config', '--local', 'user.name', 'Independent Agent'], generated, 'baseline-git-name');
run(['git', 'config', '--local', 'user.email', 'independent-agent@example.invalid'], generated, 'baseline-git-email');
run(['git', 'add', '--all'], generated, 'baseline-stage');
run(['git', 'commit', '-m', 'Generated pristine API bootstrap before feature hooks'], generated, 'baseline-bootstrap-commit');
const baselineSha = run(['git', 'rev-parse', 'HEAD'], generated, 'baseline-sha').trim();
assert.equal(run(['git', 'status', '--porcelain=v1', '--untracked-files=all'], generated, 'baseline-clean').trim(), '');
const baselineTracked = run(['git', 'ls-tree', '-r', '--full-tree', 'HEAD'], generated, 'baseline-tracked-tree');
const baselineTrackedFiles = baselineTracked.trim().split('\n').map((line) => {
  const match = /^([0-9]{6}) blob ([a-f0-9]{40})\t(.+)$/u.exec(line);
  assert.ok(match);
  const [, mode, gitBlobSha, file] = match;
  assert.ok(['100644', '100755'].includes(mode));
  assert.ok(!path.isAbsolute(file) && !file.split('/').includes('..'));
  const bytes = readFileSync(path.join(generated, file));
  return { path: file, mode, gitBlobSha, size: bytes.length, sha256: digest(bytes), bytes: bytes.toString('base64') };
});
const baselineCommitRaw = run(['git', 'cat-file', 'commit', 'HEAD'], generated, 'baseline-commit-object');
writeJson('pristine-baseline-proof.json', {
  schema: 1, head: baselineSha, parent: null,
  tree: run(['git', 'rev-parse', 'HEAD^{tree}'], generated, 'baseline-tree-sha').trim(),
  status: '', origin: baselineState.origin, contentId: baselineContentId,
  commitObject: { size: Buffer.byteLength(baselineCommitRaw), sha256: digest(Buffer.from(baselineCommitRaw)), bytes: Buffer.from(baselineCommitRaw).toString('base64') },
  trackedTree: baselineTracked, files: baselineTrackedFiles,
  classification: 'Actual pristine generated bootstrap tree; never accepted feature commit evidence',
});
run(['git', 'switch', '-c', 'feat/status'], generated, 'feature-branch');
absentSource();
run(['pnpm', 'app:new', '--', '--kind', 'api', '--name', 'status', '--no-install'], generated, 'own-cold-status-generator');
const coldState = JSON.parse(readFileSync(path.join(generated, '.template.json'), 'utf8'));
assert.deepEqual(coldState.origin, baselineState.origin);
assert.deepEqual(coldState.options, baselineState.options);
assert.equal(Object.hasOwn(coldState, 'formatKey'), false, 'Cold owning app generator must clear its inherited formatter key');
assert.ok(!existsSync(path.join(generated, 'node_modules')));
const bookkeeping = new Set(['.template.json', 'package.json', 'pnpm-lock.yaml']);
const preservedBaselineFiles = [];
for (const [file, bytes] of baselineFiles) {
  if (bookkeeping.has(file)) continue;
  assert.ok(readFileSync(path.join(generated, file)).equals(bytes), 'Generator changed existing source: ' + file);
  preservedBaselineFiles.push({ path: file, sha256: digest(bytes) });
  assert.equal(coldState.managed[file], baselineState.managed[file]);
}
const afterGenerator = inventory();
for (const file of afterGenerator.keys()) {
  assert.ok(baselineFiles.has(file) || file.startsWith('packages/status/'), 'Unexpected generated first-party path: ' + file);
}
const generatedStatusFiles = [...afterGenerator].filter(([file]) => file.startsWith('packages/status/')).map(([file, bytes]) => {
  assert.equal(coldState.managed[file], digest(bytes));
  return { path: file, sha256: digest(bytes), size: bytes.length, bytes: bytes.toString('base64') };
});
assert.ok(generatedStatusFiles.length > 0);
writeJson('raw-cold-generated-status.json', { generatedStatusFiles, coldFormatKeyAbsent: true, source: config.source });
for (const file of authored.files) {
  mkdirSync(path.dirname(path.join(generated, file.path)), { recursive: true });
  writeFileSync(path.join(generated, file.path), file.content);
  assert.equal(digest(readFileSync(path.join(generated, file.path))), file.sha256);
}
for (const [file, bytes] of afterGenerator) {
  if (authoredPaths.includes(file)) continue;
  assert.ok(readFileSync(path.join(generated, file)).equals(bytes), 'Authored migration changed scaffold/foundation: ' + file);
}
const featureContentId = contentId(generated);
run(['git', 'add', '.template.json', 'package.json', 'pnpm-lock.yaml', 'packages/status'], generated, 'candidate-stage');
const changedPaths = run(['git', 'diff', '--cached', '--name-only', '--no-renames', baselineSha], generated, 'candidate-paths').trim().split('\n').filter(Boolean);
assert.ok(changedPaths.length > 0);
assert.ok(changedPaths.every((file) => bookkeeping.has(file) || file.startsWith('packages/status/')));
const diff = run(['git', 'diff', '--cached', '--binary', '--full-index', '--no-renames', baselineSha], generated, 'candidate-patch');
mkdirSync(payload, { recursive: false });
writeFileSync(path.join(payload, 'status-feature.patch'), diff);
run(['git', 'bundle', 'create', path.join(payload, 'status-source.bundle'), 'main'], generated, 'pristine-baseline-bundle');
const input = {
  schema: 1, execution: 'hosted-tools',
  task: 'Use the generated API app generator to add GET /status with meaningful unit and real-workerd regression coverage while preserving existing applications and user files.',
  baselineSha, origin: coldState.origin, featureContentId, changedPaths,
  authoredFiles: authored.files.map(({ path, sha256 }) => ({ path, sha256 })),
  preservedBaselineFiles,
  coldGeneratorEvidence: { sourceRemoved: true, formatKeyAbsent: true, baselineContentId, managedStatusFiles: generatedStatusFiles.map(({ path, sha256 }) => ({ path, sha256 })) },
  bundleSha256: digest(readFileSync(path.join(payload, 'status-source.bundle'))),
  patchSha256: digest(readFileSync(path.join(payload, 'status-feature.patch'))),
};
assert.deepEqual(input.origin, expectedOrigin);
writeFileSync(path.join(payload, 'status-agent-input.json'), JSON.stringify(input, null, 2) + '\n');
writeJson('fresh-feature-input.json', input);
writeJson('bootstrap-classification.json', { baselineSha, baselineContentId, featureContentId, source: config.source, commands, classification: 'Generated baseline bootstrap and cold app preparation only; genuine feature Git acceptance must follow installed standard hooks' });
absentSource();
console.log('STATUS_FRESH_INPUT ' + JSON.stringify({ baselineSha, featureContentId, origin: input.origin }));
